// /status and /retry commands, well-formed A1 / storyboard / A2 buttons, and replies with notes to a storyboard request reach the
// database; anything else is ignored. Storyboard requests (WF-12) end with "ref:<token>".
const update = $input.first().json;
// /status [video id prefix] (P-017) is answered from telegram_status(); approvers only.
const statusCommand = /^\/status(?:@\w+)?(?:\s+([0-9a-fA-F-]{1,36}))?\s*$/.exec(update.message?.text ?? '');
if (update.message && statusCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'status',
      prefix: (statusCommand[1] ?? '').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /retry <video id prefix> (D-056) gives a permanently failed job one more attempt; approvers only.
const retryCommand = /^\/retry(?:@\w+)?\s+([0-9a-fA-F-]{4,36})\s*$/.exec(update.message?.text ?? '');
if (update.message && retryCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'retry',
      prefix: retryCommand[1].toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
const query = update.callback_query;
const actions = { A: 'APPROVE', G: 'REGENERATE', R: 'REJECT' };
if (query) {
  const match = /^(a1|sb|a2):([AGR]):([0-9a-f]{32})$/.exec(query.data ?? '');
  if (!match || (match[1] !== 'a1' && match[2] === 'G')) return [];
  return [{
    json: {
      kind: 'button',
      approval: { a1: 'script', sb: 'storyboard', a2: 'preview' }[match[1]],
      queryId: query.id,
      userId: String(query.from.id),
      chatId: String(query.message?.chat?.id ?? ''),
      messageId: String(query.message?.message_id ?? ''),
      originalText: String(query.message?.text ?? ''),
      action: actions[match[2]],
      token: match[3],
      note: '',
    },
  }];
}
const message = update.message;
const repliedTo = message?.reply_to_message;
const ref = /ref:([0-9a-f]{32})/.exec(repliedTo?.text ?? '');
if (!message || message.from?.is_bot || !repliedTo?.from?.is_bot || !ref || typeof message.text !== 'string') return [];
return [{
  json: {
    kind: 'reply',
    approval: 'storyboard',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    action: 'FEEDBACK',
    token: ref[1],
    note: message.text.trim(),
  },
}];

// telegram_decide() result codes -> short replies. Buttons are removed once the request is
// settled (decided, superseded, expired); a refused stranger leaves the message untouched. Replies
// with notes (storyboard or A2) are answered in the chat; both revise the storyboard.
const input = $('Parse callback').first().json;
const { result, version, round } = $input.first().json;
const storyboard = input.approval === 'storyboard';
const preview = input.approval === 'preview';
const notes = `Notes received: revising the storyboard (round ${round} of 4).`;
const done = storyboard
  ? { APPROVE: 'Approved: rendering the preview', REJECT: 'Rejected (video cancelled)', FEEDBACK: notes }
  : preview
    ? { APPROVE: 'Approved: rendering the final 1080p', REJECT: 'Rejected (video cancelled)' }
    : { APPROVE: 'Approved', REJECT: 'Rejected (video cancelled)', REGENERATE: `Regenerating as v${version}` };
const replies = {
  OK: done[input.action],
  NOT_ALLOWED: 'You are not an approver.',
  NOT_FOUND: 'Unknown approval.',
  NOT_PENDING: 'Already decided.',
  EXPIRED: 'This request expired.',
  SUPERSEDED: 'A newer version exists; this request is no longer valid.',
  HASH_MISMATCH: `The ${storyboard ? 'storyboard' : preview ? 'preview' : 'script'} changed after this request; wait for the new request.`,
  EMPTY_NOTE: 'Write your notes in the reply text.',
  NOT_SUPPORTED: 'Not available for this request.',
  NEEDS_DECISION: 'That was the last round of notes; the video needs a decision.',
};
const settled = ['OK', 'NOT_PENDING', 'EXPIRED', 'SUPERSEDED', 'NEEDS_DECISION'].includes(result);
const decidedAt = new Date().toISOString().replace('T', ' ').slice(0, 16);
const answer = replies[result] ?? `Not applied (${result}).`;
return [{
  json: {
    answer,
    settled,
    isButton: input.kind !== 'reply',
    chatId: input.chatId,
    messageId: input.messageId,
    queryId: input.queryId,
    editedText: `${input.originalText}\n\n${result === 'OK' ? 'Decision' : 'Closed'}: ${answer} (${decidedAt} UTC)`.slice(0, 4096),
  },
}];

// telegram_status() rows -> one status message (P-017). System text is English; titles are
// quoted Vietnamese video content. Times are minutes since the step or job started.
const input = $('Parse callback').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row.allowed !== undefined);
const reply = (text) => [{ json: { text: text.slice(0, 4096), chatId: input.chatId, messageId: input.messageId } }];
if (rows.some((row) => row.allowed === false)) return reply('You are not an approver.');
if (rows.length === 0) {
  return reply(input.prefix ? `[AI Video] No video id starts with ${input.prefix}.` : '[AI Video] No active videos.');
}
const minutes = (from, to = Date.now()) => {
  const m = Math.max(0, Math.round((new Date(to).getTime() - new Date(from).getTime()) / 60_000));
  return m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')} min`;
};
const describe = (p) => {
  if (!p || !p.stage) return '';
  const turn = p.turn ? ` ${p.turn}/${p.of}` : '';
  switch (p.stage) {
    case 'agent': return `agent turn${turn}`;
    case 'gates': return `checking (turn${turn})`;
    case 'tts': return `narration ${p.scene}/${p.of}`;
    case 'voice': return 'joining the voice';
    case 'whisper': return 'whisper';
    case 'render': return `rendering ${p.frames ?? ''} frames`.replace('  ', ' ');
    case 'loudness': return 'loudness';
    default: return String(p.stage);
  }
};
const head = (row) => `${String(row.video_id).slice(0, 8)} v${row.version} · ${row.title ?? '?'}`;
const cost = (row) => Object.entries(row.cost ?? {}).map(([c, v]) => `${Math.round(v * 100) / 100} ${c}`).join(', ');

if (input.prefix) {
  const row = rows[0];
  const marks = { SUCCEEDED: '✓', RUNNING: '▶', FAILED_PERMANENT: '✗', FAILED_RETRYABLE: '↻', BLOCKED: '⏸' };
  const jobs = (row.jobs ?? []).map((job) => {
    const parts = [`${marks[job.status] ?? '·'} ${job.step}`];
    if (job.started) parts.push(minutes(job.started, job.status === 'RUNNING' ? undefined : job.finished ?? undefined));
    else parts.push('waiting');
    if (job.attempts > 1) parts.push(`${job.attempts} attempts`);
    if (job.status === 'RUNNING' && describe(job.progress)) parts.push(describe(job.progress));
    if (job.error && job.status !== 'SUCCEEDED') parts.push(job.error);
    return parts.join(' · ');
  });
  return reply([
    `[AI Video] Video ${head(row)}`,
    `Status: ${row.status} (${minutes(row.status_since)})`,
    ...jobs,
    cost(row) ? `Cost: ${cost(row)}` : 'Cost: none recorded',
    ...(row.approval ? [`Waiting for: ${row.approval}`] : []),
    ...(row.status === 'NEEDS_DECISION' ? [`Retry the failed step: /retry ${String(row.video_id).slice(0, 8)}`] : []),
  ].join('\n'));
}

const lines = rows.flatMap((row) => {
  const step = row.step
    ? `${row.step} ${String(row.step_status).toLowerCase()} ${minutes(row.step_since)}`
    : 'no job yet';
  const extra = [describe(row.progress), `${row.steps_done}/${row.steps_total} jobs done`, row.approval ? `waiting for ${row.approval}` : '']
    .filter(Boolean);
  return ['', head(row), [row.status, step, ...extra].join(' · ')];
});
return reply([`[AI Video] ${rows.length} active video${rows.length === 1 ? '' : 's'}`, ...lines, '', 'Details: /status <first 8 characters of the id>'].join('\n'));

// telegram_retry() result -> one reply (D-056). System text is English.
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const id = row.video_id ? String(row.video_id).slice(0, 8) : input.prefix;
const texts = {
  RETRIED: `[AI Video] Retrying ${row.step} of video ${id} (attempt ${row.attempt}). Progress: /status ${id}`,
  NOT_APPROVER: 'You are not an approver.',
  NOT_FOUND: `[AI Video] No video id starts with ${input.prefix}.`,
  AMBIGUOUS: `[AI Video] Several video ids start with ${input.prefix}; send more characters.`,
  NOT_STOPPED: `[AI Video] Video ${id} is not waiting for a decision; nothing to retry.`,
  NO_FAILED_JOB: `[AI Video] Video ${id} has no failed job to retry.`,
};
const text = texts[row.result] ?? `[AI Video] Retry failed: ${row.result ?? 'no answer'}.`;
return [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];
